  let handle = gateway.request(gateway, main_request())
  let assert Ok(#(_deltas, stream.Settled(..))) =
    stream.await_terminal(handle, within: 1000)
  stream.cancel(handle)
  stream.cancel(handle)
  assert stream.next(handle, within: 100) == Error(Nil)
}

